from typing import List

class Solution:
    def findMedian(self, nums: List[List[int]]) -> float:
        arr = []
        for num, freq in nums:
            arr.extend([num] * freq)
        arr.sort()
        m = len(arr)
        if m % 2:
            return round(float(arr[m // 2]), 1)
        return round((arr[m // 2 - 1] + arr[m // 2]) / 2, 1)

