#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    double findMedian(vector<vector<int>>& nums) {
        vector<int> arr;
        for (auto& p : nums)
            for (int i = 0; i < p[1]; ++i) arr.push_back(p[0]);
        sort(arr.begin(), arr.end());
        int m = arr.size();
        if (m % 2) return round(arr[m / 2] * 10.0) / 10.0;
        return round((arr[m / 2 - 1] + arr[m / 2]) / 2.0 * 10.0) / 10.0;
    }
};

