import java.util.*;

class Solution {
    public double findMedian(int[][] nums) {
        List<Integer> arr = new ArrayList<>();
        for (int[] p : nums)
            for (int i = 0; i < p[1]; i++) arr.add(p[0]);
        Collections.sort(arr);
        int m = arr.size();
        if (m % 2 == 1) return Math.round(arr.get(m / 2) * 10.0) / 10.0;
        return Math.round((arr.get(m / 2 - 1) + arr.get(m / 2)) / 2.0 * 10.0) / 10.0;
    }
}

