from typing import List

class Solution:
    def findMedian(self, nums: List[List[int]]) -> float:
        total = sum(f for _, f in nums)
        lo, hi = (total - 1) // 2, total // 2
        vals = []
        c = 0
        for num, freq in sorted(nums):
            c += freq
            while len(vals) < 2 and c > lo + len(vals):
                vals.append(num)
            if len(vals) == 2:
                break
        return round(sum(vals) / len(vals), 1)

