#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    double findMedian(vector<vector<int>>& nums) {
        long long total = 0;
        for (auto& p : nums) total += p[1];
        long long lo = (total - 1) / 2, hi = total / 2;
        vector<int> vals;
        long long c = 0;
        sort(nums.begin(), nums.end());
        for (auto& p : nums) {
            c += p[1];
            while ((int)vals.size() < 2 && c > lo + (long long)vals.size())
                vals.push_back(p[0]);
            if (vals.size() == 2) break;
        }
        double med = (double)(vals[0] + vals.back()) / vals.size();
        return round(med * 10.0) / 10.0;
    }
};

