import java.util.*;

class Solution {
    public double findMedian(int[][] nums) {
        long total = 0;
        for (int[] p : nums) total += p[1];
        long lo = (total - 1) / 2, hi = total / 2;
        Arrays.sort(nums, (a, b) -> Integer.compare(a[0], b[0]));
        List<Integer> vals = new ArrayList<>();
        long c = 0;
        for (int[] p : nums) {
            c += p[1];
            while (vals.size() < 2 && c > lo + vals.size()) vals.add(p[0]);
            if (vals.size() == 2) break;
        }
        double med = (vals.get(0) + vals.get(vals.size() - 1)) / (double) vals.size();
        return Math.round(med * 10.0) / 10.0;
    }
}

