var findMedian = function(nums) {
    const total = nums.reduce((s, p) => s + p[1], 0);
    const lo = Math.floor((total - 1) / 2), hi = Math.floor(total / 2);
    const sorted = [...nums].sort((a, b) => a[0] - b[0]);
    const vals = [];
    let c = 0;
    for (const [num, freq] of sorted) {
        c += freq;
        while (vals.length < 2 && c > lo + vals.length) vals.push(num);
        if (vals.length === 2) break;
    }
    return Math.round((vals[0] + vals[vals.length - 1]) / vals.length * 10) / 10;
};

